from __future__ import annotations

from pydantic import Field
from typing_extensions import NotRequired, TypedDict

from ..core import UNSET, Optional, SdkBaseModel
from .enums.cause12 import Cause12OrStr
from .workflow_type import WorkflowType, WorkflowTypeDict


class StartChildWorkflowExecutionFailedEventAttributes(SdkBaseModel):
    workflow_type: WorkflowType = Field(alias="workflowType")
    cause: Cause12OrStr
    """The cause of the failure. This information is generated by the system and can be useful for diagnostic purposes.
    When cause is set to OPERATION_NOT_PERMITTED, the decision fails because it lacks sufficient permissions. For
    details and example IAM policies, see Using IAM to Manage Access to Amazon SWF Workflows in the Amazon SWF Developer
    Guide."""

    workflow_id: str = Field(alias="workflowId")
    """The workflowId of the child workflow execution."""

    initiated_event_id: int = Field(alias="initiatedEventId")
    """When the cause is WORKFLOW_ALREADY_RUNNING, initiatedEventId is the ID of the
    StartChildWorkflowExecutionInitiated event that corresponds to the StartChildWorkflowExecution Decision to start the
    workflow execution. You can use this information to diagnose problems by tracing back the chain of events leading up
    to this event. When the cause isn't WORKFLOW_ALREADY_RUNNING, initiatedEventId is set to 0 because the
    StartChildWorkflowExecutionInitiated event doesn't exist."""

    decision_task_completed_event_id: int = Field(alias="decisionTaskCompletedEventId")
    """The ID of the DecisionTaskCompleted event corresponding to the decision task that resulted in the
    StartChildWorkflowExecution Decision to request this child workflow execution. This information can be useful for
    diagnosing problems by tracing back the chain of events."""

    control: Optional[str] = UNSET
    """The data attached to the event that the decider can use in subsequent workflow tasks. This data isn't sent to the
    child workflow execution."""


class StartChildWorkflowExecutionFailedEventAttributesDict(TypedDict):
    workflow_type: WorkflowTypeDict
    cause: Cause12OrStr
    workflow_id: str
    initiated_event_id: int
    decision_task_completed_event_id: int
    control: NotRequired[str]
